        jdbc.query("SELECT person_id, total FROM period_person_total WHERE sheet_id = ? AND period_id = ? ORDER BY person_id",
                (ResultSet rs) -> {
                    totals.put(rs.getLong("person_id"), rs.getBigDecimal("total").setScale(2));
                }, period.sheetId(), period.id());
