package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.opening.OpeningRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Adds each person's open figure at the end of the old year's last period (see PeriodCloser#openAt, over the old
 *  year's periods) to their carried figure for the new year's first period (the earliest period whose from-date falls
 *  in it), written as OPENING_SET; a person with nothing open gets no line, and nothing is carried when that period was
 *  not generated by this rollover (the year was rolled over already). Keeps the rollover, with the periods it
 *  generated and the openings it set, so it can be undone (see UndoRollover). Then writes ROLLOVER. */
public class CarryRollover {
    public void carry(@PathVariable("sheetId") String sheetId, @Val RolloverValues rollover,
            @Val GeneratePeriodsValues values, @Val GeneratedPeriods generated, PeriodRepository periods,
            PeriodCloser closer, PersonRepository people, OpeningRepository openings, RolloverRepository rollovers, Audit audit) {
        String sheet = sheetId.trim();
        Period last = rollover.oldPeriods().get(rollover.oldPeriods().size() - 1);
        Map<Long, BigDecimal> open = closer.openAt(sheet, rollover.oldPeriods(), last.to());
        Period first = periods.list(sheet).stream()
                .filter((p) -> !p.from().isBefore(values.from()) && !p.from().isAfter(values.to()))
                .min(Comparator.comparing(Period::from)).orElse(null);
        List<Long> set = new ArrayList<>();
# POST /api/sheets/{sheetId}/periods/rollover — roll a fiscal year (yyyy, FY<yyyy>) over: generate the next fiscal
# year's twelve periods exactly as generate-fy does, then add each person's open figure at the end of the old year's
# last period (the due of their claims that count, belonging to a period of the old year, OPEN or PENDING at that
# period's end) to their carried figure for the new year's first period, written as OPENING_SET; then ROLLOVER. A year
# that is not yyyy, a fiscal year with no periods, or anyone but a steward is a 400 and writes nothing. Responds with
# how many periods were made.

